        int Function(
          ffi.Pointer<kiln_context>,
          ffi.Pointer<kiln_media>,
          ffi.Pointer<kiln_transcribe_options>,
          kiln_token_cb,
          ffi.Pointer<ffi.Void>,
          ffi.Pointer<kiln_transcribe_stats>,
        )
      >();

  void kiln_set_log_callback(kiln_log_cb cb, ffi.Pointer<ffi.Void> user) {
    return _kiln_set_log_callback(cb, user);
  }

  late final _kiln_set_log_callbackPtr =
      _lookup<
        ffi.NativeFunction<
          ffi.Void Function(kiln_log_cb, ffi.Pointer<ffi.Void>)
        >
      >('kiln_set_log_callback');
  late final _kiln_set_log_callback = _kiln_set_log_callbackPtr
      .asFunction<void Function(kiln_log_cb, ffi.Pointer<ffi.Void>)>();

  void kiln_set_log_level(kiln_log_level level) {
    return _kiln_set_log_level(level.value);
  }

  late final _kiln_set_log_levelPtr =
      _lookup<ffi.NativeFunction<ffi.Void Function(ffi.UnsignedInt)>>(
        'kiln_set_log_level',
      );
  late final _kiln_set_log_level = _kiln_set_log_levelPtr
      .asFunction<void Function(int)>();
}

/// ------------------------------------------------------------------ */
/// /* Status                                                              */
/// /* ------------------------------------------------------------------
enum kiln_status {
  KILN_OK(0),
  KILN_ERR_INVALID_ARG(1),

  /// no backend can run this model on this device
  KILN_ERR_NO_BACKEND(2),

  /// file missing, corrupt, unsupported arch
  KILN_ERR_MODEL_LOAD(3),
  KILN_ERR_OUT_OF_MEMORY(4),
  KILN_ERR_CONTEXT_FULL(5),
  KILN_ERR_CANCELLED(6),

  /// backend-specific failure; see kiln_last_error
  KILN_ERR_BACKEND(7),
  KILN_ERR_NOT_SUPPORTED(8),
  KILN_ERR_INTERNAL(99);

  final int value;
  const kiln_status(this.value);

  static kiln_status fromValue(int value) => switch (value) {
    0 => KILN_OK,
    1 => KILN_ERR_INVALID_ARG,
    2 => KILN_ERR_NO_BACKEND,
    3 => KILN_ERR_MODEL_LOAD,
    4 => KILN_ERR_OUT_OF_MEMORY,
    5 => KILN_ERR_CONTEXT_FULL,
    6 => KILN_ERR_CANCELLED,
    7 => KILN_ERR_BACKEND,
    8 => KILN_ERR_NOT_SUPPORTED,
    99 => KILN_ERR_INTERNAL,
    _ => throw ArgumentError('Unknown value for kiln_status: $value'),
  };
}

/// ------------------------------------------------------------------ */
/// /* Backends                                                            */
/// /* ------------------------------------------------------------------
enum kiln_backend_kind {
  /// probe device, pick best available
  KILN_BACKEND_AUTO(0),

  /// llama.cpp, CPU only. Guaranteed tier.
  KILN_BACKEND_CPU(1),

  /// llama.cpp, Metal / Vulkan / OpenCL
  KILN_BACKEND_GPU(2),

  /// vendor NPU (QNN, etc). Detected, never assumed.
  KILN_BACKEND_NPU(3);

  final int value;
  const kiln_backend_kind(this.value);

  static kiln_backend_kind fromValue(int value) => switch (value) {
    0 => KILN_BACKEND_AUTO,
    1 => KILN_BACKEND_CPU,
    2 => KILN_BACKEND_GPU,
    3 => KILN_BACKEND_NPU,
    _ => throw ArgumentError('Unknown value for kiln_backend_kind: $value'),
  };
}

/// ------------------------------------------------------------------ */
/// /* Device probe                                                        */
/// /* ------------------------------------------------------------------
final class kiln_device_info extends ffi.Struct {
  /// e.g. "Qualcomm SM8650", "Apple M4 Pro"
  @ffi.Array.multi([64])
  external ffi.Array<ffi.Char> soc;

  /// e.g. "arm64-v8a"
  @ffi.Array.multi([16])
  external ffi.Array<ffi.Char> abi;

  @ffi.Int32()
  external int cpu_cores;

  /// cores kiln treats as fast: all but the little cores, = cpu_cores if unknown
  @ffi.Int32()
  external int cpu_big_cores;

  /// bitmask of those cores (bit i = cpu i); 0 = no affinity info
  @ffi.Uint64()
  external int cpu_fast_mask;

  @ffi.Uint64()
  external int ram_total_bytes;

  @ffi.Uint64()
  external int ram_available_bytes;

  @ffi.Bool()
  external bool has_fp16;

  /// ARMv8.2 dot product (big win for Q4/Q8)
  @ffi.Bool()
  external bool has_dotprod;

  /// ARMv8.6 int8 matmul
  @ffi.Bool()
  external bool has_i8mm;

  @ffi.Bool()
  external bool has_sve;

  /// a usable GPU backend compiled in and present
  @ffi.Bool()
  external bool has_gpu;

  @ffi.Array.multi([64])
  external ffi.Array<ffi.Char> gpu_name;

  @ffi.Bool()
  external bool has_npu;

  @ffi.Array.multi([64])
  external ffi.Array<ffi.Char> npu_name;
}

final class kiln_model extends ffi.Opaque {}

final class kiln_model_params extends ffi.Struct {
  /// KILN_BACKEND_AUTO recommended
  @ffi.UnsignedInt()
  external int backendAsInt;

  kiln_backend_kind get backend => kiln_backend_kind.fromValue(backendAsInt);

  /// -1 = all if GPU chosen, 0 = none
  @ffi.Int32()
  external int n_gpu_layers;

  /// 0 = auto from probe
  @ffi.Int32()
  external int n_threads;

  @ffi.Bool()
  external bool use_mmap;

  @ffi.Bool()
  external bool use_mlock;
}

/// What actually happened. This is the truth-telling API.
final class kiln_model_info extends ffi.Struct {
  @ffi.UnsignedInt()
  external int backend_usedAsInt;

  kiln_backend_kind get backend_used =>
      kiln_backend_kind.fromValue(backend_usedAsInt);

  /// e.g. "llama.cpp/metal", "llama.cpp/cpu"
  @ffi.Array.multi([64])
  external ffi.Array<ffi.Char> backend_name;

  /// e.g. "llama", "qwen2", "gemma3"
  @ffi.Array.multi([32])
  external ffi.Array<ffi.Char> arch;

  /// e.g. "Q4_K_M"
  @ffi.Array.multi([16])
  external ffi.Array<ffi.Char> quant;

  @ffi.Int64()
  external int n_params;

  @ffi.Int32()
  external int n_ctx_train;

  @ffi.Int32()
  external int n_vocab;

  @ffi.Int32()
  external int n_gpu_layers_used;

  /// resident weight memory
  @ffi.Uint64()
  external int model_bytes;

  /// chat template has a reasoning switch (Qwen3.x, Gemma 4, ...)
  @ffi.Bool()
  external bool supports_thinking;

  /// answers typed questions with kiln_decide; cannot generate text
  @ffi.Bool()
  external bool is_decision_model;

  /// turns text into a vector with kiln_embed; cannot generate text
  @ffi.Bool()
  external bool is_embedding_model;

  /// embedding models: length of the vector kiln_embed returns; else 0
  @ffi.Int32()
  external int n_embd;

  /// writes down audio with kiln_transcribe and needs no projector (Whisper, Parakeet);
  /// cannot generate text. Qwen3-ASR is a chat-style model plus a projector, so it reads false
  @ffi.Bool()
  external bool is_speech_model;
}

final class kiln_context extends ffi.Opaque {}

final class kiln_context_params extends ffi.Struct {
  /// 0 = model default, capped by RAM
  @ffi.Int32()
  external int n_ctx;

  @ffi.Int32()
  external int n_batch;

  @ffi.Bool()
  external bool flash_attn;
}

final class kiln_chat_message extends ffi.Struct {
  /// "system" | "user" | "assistant"
  external ffi.Pointer<ffi.Char> role;

  external ffi.Pointer<ffi.Char> content;
}

final class kiln_chat_options extends ffi.Struct {
  /// append the "assistant:" turn opener (true for generation)
  @ffi.Bool()
  external bool add_assistant_prefix;

  /// reasoning models only. false = answer directly. Ignored if unsupported.
  @ffi.Bool()
  external bool enable_thinking;

  /// thinking budget, kiln_chat only: after this many reasoning tokens kiln closes
  /// the think block itself and the model goes on to answer. <= 0 = unlimited.
  /// Small models often never stop thinking on their own.
  @ffi.Int32()
  external int max_reasoning_tokens;
}

/// ------------------------------------------------------------------ */
/// /* Generation                                                          */
/// /* ------------------------------------------------------------------
final class kiln_sampling_params extends ffi.Struct {
  /// <= 0 = greedy
  @ffi.Float()
  external double temperature;

  @ffi.Float()
  external double top_p;

  @ffi.Int32()
  external int top_k;

  @ffi.Float()
  external double min_p;

  @ffi.Float()
  external double repeat_penalty;

  @ffi.Int32()
  external int repeat_last_n;

  /// 0 = random
  @ffi.Uint32()
  external int seed;

  /// <= 0 = until EOS or context full
  @ffi.Int32()
  external int max_tokens;
}

enum kiln_channel {
  KILN_CHANNEL_ANSWER(0),

  /// text inside the model's think block; tags themselves are stripped
  KILN_CHANNEL_REASONING(1);

  final int value;
  const kiln_channel(this.value);

  static kiln_channel fromValue(int value) => switch (value) {
    0 => KILN_CHANNEL_ANSWER,
    1 => KILN_CHANNEL_REASONING,
    _ => throw ArgumentError('Unknown value for kiln_channel: $value'),
  };
}

typedef kiln_token_cbFunction =
    ffi.Bool Function(
      ffi.UnsignedInt channel,
      ffi.Pointer<ffi.Char> piece,
      ffi.Int32 token_id,
      ffi.Pointer<ffi.Void> user,
    );
typedef Dartkiln_token_cbFunction =
    bool Function(
      kiln_channel channel,
      ffi.Pointer<ffi.Char> piece,
      int token_id,
      ffi.Pointer<ffi.Void> user,
    );

/// Called once per generated token piece. Return false to stop generation.
/// Pieces are UTF-8 but a multi-byte character may be split across calls.
typedef kiln_token_cb = ffi.Pointer<ffi.NativeFunction<kiln_token_cbFunction>>;

final class kiln_gen_stats extends ffi.Struct {
  /// total tokens in the rendered prompt
  @ffi.Int32()
  external int prompt_tokens;

  /// of those, how many were already in the KV cache (multi-turn)
  @ffi.Int32()
  external int cached_tokens;

  @ffi.Int32()
  external int generated_tokens;

  /// subset of generated_tokens that went to the reasoning channel
  @ffi.Int32()
  external int reasoning_tokens;

  @ffi.Double()
  external double prompt_ms;

  @ffi.Double()
  external double gen_ms;

  @ffi.Double()
  external double prompt_tps;

  @ffi.Double()
  external double gen_tps;

  @ffi.Bool()
  external bool stopped_by_eos;

  @ffi.Bool()
  external bool stopped_by_user;

  /// max_reasoning_tokens was reached and kiln closed the think block
  @ffi.Bool()
  external bool reasoning_truncated;
}

/// A decision model (kiln_model_info.is_decision_model) does not write text. It reads a
/// state and one typed question and returns a probability per option, in one forward pass.
/// Supported today: LFM2 d1-omni, text state only (no images or audio).
enum kiln_question_type {
  /// yes / no
  KILN_QUESTION_NOUL(0),

  /// pick one of the options
  KILN_QUESTION_CHOICE(1),

  /// rate on a scale; options are the levels, lowest first (2 to 10)
  KILN_QUESTION_SCORE(2);

  final int value;
  const kiln_question_type(this.value);

  static kiln_question_type fromValue(int value) => switch (value) {
    0 => KILN_QUESTION_NOUL,
    1 => KILN_QUESTION_CHOICE,
    2 => KILN_QUESTION_SCORE,
    _ => throw ArgumentError('Unknown value for kiln_question_type: $value'),
  };
}

final class kiln_decision_option extends ffi.Struct {
  /// choice: the label returned. noul: "true" or "false" (also "yes" / "no"). score: ignored
  external ffi.Pointer<ffi.Char> key;

  /// what the option means; may be NULL
  external ffi.Pointer<ffi.Char> description;
}

final class kiln_decision_question extends ffi.Struct {
  /// short name of the question, e.g. "wants_refund"
  external ffi.Pointer<ffi.Char> id;

  @ffi.UnsignedInt()
  external int typeAsInt;

  kiln_question_type get type => kiln_question_type.fromValue(typeAsInt);

  /// the question itself
  external ffi.Pointer<ffi.Char> instructions;

  /// noul: optional, only to describe what yes and no mean
  external ffi.Pointer<kiln_decision_option> options;

  @ffi.Int32()
  external int n_options;
}

final class kiln_decision_answer extends ffi.Struct {
  /// probabilities written to probs. noul: 2, [0] = no, [1] = yes
  @ffi.Int32()
  external int n_probs;

  /// index of the most probable entry
  @ffi.Int32()
  external int best;

  /// noul: P(yes). score: expected level, 0 .. n-1. choice: P(best)
  @ffi.Float()
  external double value;

  /// 0 .. 1 for choice and score; for noul how far P(yes) is from 0.5
  @ffi.Float()
  external double confidence;

  @ffi.Int32()
  external int prompt_tokens;

  @ffi.Double()
  external double ms;
}

/// An embedding model (kiln_model_info.is_embedding_model) does not write text. It turns a
/// text into a list of numbers; texts with a similar meaning get similar lists. With
/// normalised vectors the similarity of two texts is their dot product (1 = same meaning).
/// Tested with EmbeddingGemma 2 and nomic-embed-text v1.5.
/// Some embedding models also take images and audio and put them in the same space as text,
/// so a text query can find a photo. Those need a second file, the projector (an "mmproj"
/// GGUF): see kiln_model_load_projector and kiln_embed_media.
enum kiln_embed_kind {
  /// embed the text exactly as given
  KILN_EMBED_RAW(0),

  /// a search query: kiln adds the model's query prefix
  KILN_EMBED_QUERY(1),

  /// a text to be searched: kiln adds the model's document prefix
  KILN_EMBED_DOCUMENT(2);

  final int value;
  const kiln_embed_kind(this.value);

  static kiln_embed_kind fromValue(int value) => switch (value) {
    0 => KILN_EMBED_RAW,
    1 => KILN_EMBED_QUERY,
    2 => KILN_EMBED_DOCUMENT,
    _ => throw ArgumentError('Unknown value for kiln_embed_kind: $value'),
  };
}

final class kiln_embed_options extends ffi.Struct {
  /// use QUERY and DOCUMENT for search; a model with no known prefix treats all as RAW
  @ffi.UnsignedInt()
  external int kindAsInt;

  kiln_embed_kind get kind => kiln_embed_kind.fromValue(kindAsInt);

  /// DOCUMENT only, optional: the document's title, for models that take one
  external ffi.Pointer<ffi.Char> title;

  /// keep only the first N numbers (smaller to store). <= 0 = the full vector.
  /// Only models trained for it stay accurate (EmbeddingGemma: 512, 256, 128)
  @ffi.Int32()
  external int dimensions;

  /// scale the vector to length 1
  @ffi.Bool()
  external bool normalize;
}

final class kiln_embed_stats extends ffi.Struct {
  /// tokens the model read: text, prefix and media together
  @ffi.Int32()
  external int tokens;

  /// of those, how many came from images and audio
  @ffi.Int32()
  external int media_tokens;

  /// numbers written to out
  @ffi.Int32()
  external int dimensions;

  /// a task prefix was added
  @ffi.Bool()
  external bool prefixed;

  /// time inside the image / audio encoders only
  @ffi.Double()
  external double media_ms;

  /// total, media_ms included
  @ffi.Double()
  external double ms;
}

/// ---- images and audio ----
final class kiln_projector_params extends ffi.Struct {
  /// most tokens one image may take. A large photo is scaled down to fit.
  /// Time grows much faster than this number. 0 = 280, < 0 = the model's own limit
  @ffi.Int32()
  external int image_max_tokens;
}

final class kiln_projector_info extends ffi.Struct {
  @ffi.Bool()
  external bool supports_images;

  @ffi.Bool()
  external bool supports_audio;
}

/// One image or one audio clip: either a file path, or the bytes of such a file.
/// Images: jpg, png, bmp, gif. Audio: wav, mp3, flac. The kind is read from the content.
final class kiln_media extends ffi.Struct {
  /// file to read, or NULL to use data
  external ffi.Pointer<ffi.Char> path;

  /// contents of an image / audio file, when path is NULL
  external ffi.Pointer<ffi.Uint8> data;

  /// bytes in data
  @ffi.Size()
  external int size;
}

/// A speech model writes down what is said in an audio clip. Two kinds are supported:
/// - Whisper and Parakeet files from whisper.cpp ("ggml-base-q5_1.bin", "ggml-parakeet-tdt-0.6b-v3-q8_0.bin").
/// kiln_model_load takes them like a GGUF; the encoder is built in, so no projector is
/// needed and kiln_model_info.is_speech_model is true. Create a context and call kiln_transcribe.
/// - Qwen3-ASR, a small text model plus an audio encoder (its projector, an "mmproj" GGUF):
/// load the model, load the projector with kiln_model_load_projector, then transcribe.
/// Tested with Whisper base (q5_1), Parakeet TDT 0.6B v3 (q8_0) and Qwen3-ASR 0.6B (Q8_0).
final class kiln_transcribe_options extends ffi.Struct {
  /// the language spoken, e.g. "English", when known. NULL = the model works it out.
  /// Parakeet does not take a hint; an English-only Whisper file refuses another language
  external ffi.Pointer<ffi.Char> language;

  /// Qwen3-ASR: replaces the instruction (NULL = "Transcribe audio to text").
  /// Whisper: a text the words may follow on from (names, spellings). Parakeet: ignored
  external ffi.Pointer<ffi.Char> prompt;

  /// <= 0 = until the model stops or the context is full. Whisper: per 30-second window. Parakeet: ignored
  @ffi.Int32()
  external int max_tokens;
}

final class kiln_transcribe_stats extends ffi.Struct {
  /// length of the clip
  @ffi.Double()
  external double audio_seconds;

  /// tokens the clip took in the context
  @ffi.Int32()
  external int audio_tokens;

  /// instruction and audio together
  @ffi.Int32()
  external int prompt_tokens;

  @ffi.Int32()
  external int generated_tokens;

  /// audio encoder: sound to audio tokens
  @ffi.Double()
  external double encode_ms;

  /// the model reading the instruction and the audio tokens
  @ffi.Double()
  external double prompt_ms;

  /// the model writing the words
  @ffi.Double()
  external double gen_ms;

  /// whole call, reading the file included. Faster than real time when ms < audio_seconds * 1000
  @ffi.Double()
  external double ms;

  /// the language as the model named it, e.g. "English"; empty if it did not say
  /// (Parakeet never does). Qwen3-ASR writes "None" when it hears no speech
  @ffi.Array.multi([32])
  external ffi.Array<ffi.Char> language;

  /// the model finished by itself (false = cut by max_tokens, the context or the caller)
  @ffi.Bool()
  external bool stopped_by_eos;

  @ffi.Bool()
  external bool stopped_by_user;
}

/// ------------------------------------------------------------------ */
/// /* Logging                                                             */
/// /* ------------------------------------------------------------------
enum kiln_log_level {
  KILN_LOG_ERROR(0),
  KILN_LOG_WARN(1),
  KILN_LOG_INFO(2),
  KILN_LOG_DEBUG(3);

  final int value;
  const kiln_log_level(this.value);

  static kiln_log_level fromValue(int value) => switch (value) {
    0 => KILN_LOG_ERROR,
    1 => KILN_LOG_WARN,
    2 => KILN_LOG_INFO,
    3 => KILN_LOG_DEBUG,
    _ => throw ArgumentError('Unknown value for kiln_log_level: $value'),
  };
}

typedef kiln_log_cbFunction =
    ffi.Void Function(
      ffi.UnsignedInt level,
      ffi.Pointer<ffi.Char> msg,
      ffi.Pointer<ffi.Void> user,
    );
typedef Dartkiln_log_cbFunction =
    void Function(
      kiln_log_level level,
      ffi.Pointer<ffi.Char> msg,
      ffi.Pointer<ffi.Void> user,
    );
typedef kiln_log_cb = ffi.Pointer<ffi.NativeFunction<kiln_log_cbFunction>>;

const int KILN_VERSION_MAJOR = 0;

const int KILN_VERSION_MINOR = 4;

const int KILN_VERSION_PATCH = 0;

const String KILN_MEDIA_MARKER = '<__media__>';
